const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const money = value => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 }).format(Number(value) || 0);
const qty = value => Number(value || 0).toLocaleString('en-US', { maximumFractionDigits: 8 });
const time = value => value ? new Date(value).toLocaleString('es', { dateStyle: 'short', timeStyle: 'short' }) : '—';

const MODEL_CATALOG = [
  { id: 'gpt-5.6-luna', label: 'GPT-5.6 Luna · económico', note: 'Predeterminado para Auto-Paper', inputPer1k: 0.0002, outputPer1k: 0.0012 },
  { id: 'gpt-5.6-terra', label: 'GPT-5.6 Terra · equilibrado', note: 'Más capacidad, mayor coste', inputPer1k: 0.002, outputPer1k: 0.012 },
  { id: 'gpt-5.6-sol', label: 'GPT-5.6 Sol · avanzado', note: 'Análisis profesional complejo', inputPer1k: 0.004, outputPer1k: 0.02 },
  { id: 'gpt-6-astra', label: 'GPT-6 Astra · máxima capacidad', note: 'Mayor coste por análisis', inputPer1k: 0.01, outputPer1k: 0.05 },
  { id: 'gpt-4o-mini', label: 'GPT-4o mini · compatibilidad', note: 'Modelo anterior' }
];
function modelOptions(selected) { const known = MODEL_CATALOG.some(item => item.id === selected); return MODEL_CATALOG.map(item => `<option value="${item.id}" ${item.id === selected ? 'selected' : ''}>${item.label}</option>`).join('') + `<option value="__custom__" ${known ? '' : 'selected'}>Modelo personalizado…</option>`; }
function chosenModel(selectId, customId) { const selected = $(selectId)?.value; return selected === '__custom__' ? $(customId)?.value.trim() : selected; }
function bindModelPicker(selectId, customId) { const select = $(selectId), custom = $(customId); if (!select || !custom) return; const sync = () => { custom.hidden = select.value !== '__custom__'; custom.required = select.value === '__custom__'; }; select.onchange = sync; sync(); }
function knownModelPricing(model) { return MODEL_CATALOG.find(item => item.id === model && Number.isFinite(item.inputPer1k) && Number.isFinite(item.outputPer1k)) || null; }

let snapshot = null;
let page = 'dashboard';
let analysis = null;
let marketData = null;

async function boot() {
  snapshot = await window.traderAPI.snapshot();
  window.traderAPI.onPaperState(state => { snapshot.state=state; if(page==='dashboard')renderDashboard(); });
  subscribeSymbols(['BTCUSDT', 'ETHUSDT', 'SOLUSDT', ...snapshot.state.positions.map(item => item.symbol)]);
  window.traderAPI.onMarketTick(tick => {
    terminalTick(tick);
    if (tick.state) snapshot.state = tick.state;
    if (analysis && analysis.symbol === tick.symbol) analysis.price = tick.price;
    if (page === 'dashboard') renderDashboard();
    if (page === 'analyze' && analysis && analysis.symbol === tick.symbol) drawAnalysis(analysis);
  });
  window.traderAPI.onAutomationUpdate(automation => { snapshot.state.automation = automation; if (automation.status === 'stopped' || automation.status === 'paused') snapshot.settings.automationEnabled = false; if (page === 'dashboard') renderDashboard(); if (page === 'agents') renderAgents(); });
  window.traderAPI.onAutomationProgress(progress => { snapshot.state.automation = { ...(snapshot.state.automation || {}), progress: [...(snapshot.state.automation?.progress || []), progress].slice(-80) }; if (page === 'dashboard') renderDashboard(); if (page === 'agents') renderAgents(); });
  window.traderAPI.onPaperAlert(alert => { snapshot.state.alerts = [alert, ...(snapshot.state.alerts || []).filter(item => item.id !== alert.id)].slice(0, 100); if (page === 'dashboard') renderDashboard(); });
  window.traderAPI.onBrokerUpdate(broker => { snapshot.broker = broker; if (page === 'live') updateBrokerStatus(broker); });
  $('#clock').textContent = new Intl.DateTimeFormat('es', { dateStyle: 'medium' }).format(new Date());
  $('#paperWorkspace').onclick=()=>navigate('dashboard');
  $('#liveWorkspace').onclick=()=>navigate('live');
  $$('[data-page]').forEach(button => button.addEventListener('click', () => navigate(button.dataset.page)));
  updateKeyStatus();
  render();
  setInterval(async () => { if (page !== 'dashboard') return; try { snapshot.state = await window.traderAPI.refreshPaper(); renderDashboard(); } catch { /* keep last known values */ } }, 60000);
}

function $$(selector) { return [...document.querySelectorAll(selector)]; }
function subscribeSymbols(symbols) { window.traderAPI.subscribeMarket([...new Set(symbols.filter(Boolean))]).catch(() => {}); }
function navigate(next) { page = next; render(); }
function updateKeyStatus() { $('#keyStatus').classList.toggle('online', snapshot.hasApiKey); $('#keyStatusText').textContent = snapshot.hasApiKey ? 'LLM configurado' : 'LLM sin configurar'; }
function render() {
  $$('[data-page]').forEach(button => button.classList.toggle('active', button.dataset.page === page));
  $('#paperWorkspace')?.classList.toggle('selected', page !== 'live'); $('#paperWorkspace')?.setAttribute('aria-selected', String(page !== 'live')); $('#liveWorkspace')?.classList.toggle('selected', page === 'live'); $('#liveWorkspace')?.setAttribute('aria-selected', String(page === 'live'));
  $$('.view-tab').forEach(button => button.classList.toggle('active', button.dataset.page === page));
  const labels = { dashboard: ['SIMULACIÓN', 'Terminal', 'Mercado real · capital virtual'], analyze: ['RESEARCH', 'Analizar mercado', 'Datos reales, análisis estructurado y ejecución simulada.'], agents: ['SIMULACIÓN', 'Agentes', 'Estado, decisiones y actividad auditable de Auto-Paper.'], research: ['RESEARCH', 'Investigación', 'Backtesting, replay y comparación de estrategias.'], settings: ['SYSTEM', 'Configuración', 'Parámetros de conexión, simulación y seguridad.'], live: ['REAL · READ ONLY', 'Cuenta real', 'Conexión verificada sin envío de órdenes.'] };
  $('#eyebrow').textContent = labels[page][0]; $('#pageTitle').textContent = labels[page][1]; $('#pageSubtitle').textContent = labels[page][2];
  ({ dashboard: renderDashboard, analyze: renderAnalyze, agents: renderAgents, research: renderResearch, settings: renderSettings, live: renderLive }[page])();
}

function agentStatusClass(status) { return ['failed', 'rejected', 'interrupted'].includes(status) ? 'sell' : ['running', 'caution', 'degraded', 'unavailable'].includes(status) ? 'amber' : status === 'completed' ? '' : 'idle'; }
function renderAgents() {
  const automation = snapshot.state.automation || {}, progress = [...(automation.progress || [])].reverse(), history = automation.history || [], last = snapshot.state.lastAnalysis || {};
  const roster = [
    ['market-data', 'Datos de mercado', 'Valida velas, cotización y frescura.'], ['technical-agent', 'Técnico', 'Interpreta indicadores calculados por código.'], ['news-agent', 'Noticias', 'Pondera titulares por fuente y recencia.'], ['liquidity-agent', 'Liquidez', 'Revisa spread, profundidad e imbalance.'], ['llm-analyst', 'Analista LLM', 'Propone una TradeIntent estructurada.'], ['intent-validator', 'Validador', 'Rechaza schemas y niveles incoherentes.'], ['critical-agent', 'Crítico', 'Busca contradicciones y puede vetar.'], ['portfolio-agent', 'Cartera', 'Controla concentración y exposición.'], ['consensus-agent', 'Consenso', 'Agrega evidencia sin saltarse riesgo.'], ['risk-governor', 'Risk Governor', 'Autoriza tamaño y ejecución paper.']
  ];
  const latestByAgent = new Map(); for (const event of progress) if (!latestByAgent.has(event.agent || event.phase)) latestByAgent.set(event.agent || event.phase, event);
  const statusLabel = automation.status === 'running' ? 'EJECUTANDO' : automation.status === 'starting' ? 'INICIANDO' : automation.status === 'paused' ? 'PAUSADO' : automation.status === 'interrupted' ? 'INTERRUMPIDO' : automation.status === 'completed-with-errors' ? 'CON ERRORES' : automation.status === 'stopped' ? 'DETENIDO' : 'EN ESPERA';
  $('#page').innerHTML = `<div class="agent-command"><section class="card agent-hero"><div><p class="section-kicker">AUTO-PAPER CONTROL</p><h2>Orquestador <span class="tag ${agentStatusClass(automation.status)}">${statusLabel}</span></h2><p>${automation.pausedReason ? esc(automation.pausedReason) : 'Los agentes analizan; el motor de riesgo conserva la autoridad de ejecución.'}</p><button class="btn primary agent-start-action" id="startAgentsPage" ${automation.status === 'running' || automation.status === 'starting' ? 'disabled' : ''}>${automation.status === 'running' || automation.status === 'starting' ? 'Agentes activos' : 'Iniciar agentes'}</button></div><div class="agent-hero-stats"><span><small>ÚLTIMA DECISIÓN</small><strong>${esc(automation.lastDecision || 'N/D')}</strong></span><span><small>HEARTBEAT</small><strong>${time(automation.heartbeatAt)}</strong></span><span><small>DURACIÓN</small><strong>${automation.durationMs == null ? '—' : `${Number(automation.durationMs)} ms`}</strong></span></div></section>
  <section class="agent-roster">${roster.map(([id, name, description]) => { const event = latestByAgent.get(id), status = event?.status || 'idle'; return `<article class="card agent-card"><div><i class="agent-dot ${agentStatusClass(status)}"></i><small>${esc(id)}</small></div><h3>${esc(name)}</h3><p>${esc(event?.detail || description)}</p><footer><span class="tag ${agentStatusClass(status)}">${esc(status)}</span><time>${event ? time(event.at) : 'Sin actividad'}</time></footer></article>`; }).join('')}</section>
  <div class="grid agent-lower"><section class="card agent-feed"><div class="card-header"><div><p class="section-kicker">LIVE TRACE</p><h2>Qué están haciendo</h2><p>Eventos persistidos de las últimas corridas.</p></div><span class="tag">${progress.length} EVENTOS</span></div>${progress.length ? `<div class="agent-activity-list">${progress.slice(0, 40).map(item => `<div class="agent-activity-row"><span class="tag ${agentStatusClass(item.status)}">${esc(item.status)}</span><strong>${esc(item.agent || item.phase)}</strong><span>${esc(item.symbol || 'sistema')} · ${esc(item.detail)}</span><small>${time(item.at)}</small></div>`).join('')}</div>` : '<div class="empty">Aún no hay actividad. Inicia Auto-Paper desde Configuración.</div>'}</section>
  <section class="card run-history"><div class="card-header"><div><p class="section-kicker">RUN JOURNAL</p><h2>Corridas recientes</h2></div></div>${history.length ? history.slice(0, 12).map(run => `<div class="run-row"><div><strong>${esc((run.symbols || []).join(', ') || 'sistema')}</strong><small>${time(run.startedAt)} · ${Number(run.durationMs || 0)} ms</small></div><span class="tag ${agentStatusClass(run.status)}">${esc(run.status)}</span><p>${(run.events || []).length} decisiones/eventos</p></div>`).join('') : '<div class="empty">Sin corridas registradas.</div>'}</section></div>
  ${last.consensus ? `<section class="card last-consensus"><div class="card-header"><div><p class="section-kicker">ÚLTIMO CONSENSO</p><h2>${esc(last.symbol)} · ${esc(last.consensus.decision)}</h2><p>${esc(last.consensus.rationale)}</p></div><span class="decision ${esc(last.consensus.decision)}">${esc(last.consensus.decision)}</span></div></section>` : ''}</div>`;
  $('#startAgentsPage')?.addEventListener('click', () => openAutomationStartModal('agents'));
}

function renderAlerts(alerts = []) {
  if (!alerts.length) return '';
  return `<section class="alerts-strip"><div class="alerts-heading"><span>ALERTAS</span><small>${alerts.length} registradas · últimos eventos</small></div>${alerts.slice(0, 3).map(alert => `<div class="alert-item alert-${esc(alert.severity || 'info')}"><i></i><span>${esc(alert.message)}<small>${time(alert.createdAt)}</small></span></div>`).join('')}</section>`;
}

function renderPerformance() {
  function renderAutomationActivity(progress = []) {
    const items = progress.slice(-10).reverse();
    if (!items.length) return '';
    return '<section class="card settings-card automation-activity"><div class="card-header"><div><p class="section-kicker">AUTOMATION ACTIVITY</p><h2>Agentes y operaciones</h2><p>Cada paso se registra mientras Auto-Paper comprueba, analiza y ejecuta.</p></div><span class="tag">' + items.length + ' EVENTOS</span></div><div class="agent-activity-list">' + items.map(item => '<div class="agent-activity-row"><span class="tag ' + (item.status === 'rejected' || item.status === 'failed' ? 'sell' : item.status === 'running' ? 'amber' : '') + '">' + esc(item.status) + '</span><strong>' + esc(item.agent || item.phase) + '</strong><span>' + esc(item.symbol || 'sistema') + ' · ' + esc(item.detail) + '</span><small>' + time(item.at) + '</small></div>').join('') + '</div></section>';
  }
  const { cash, positions = [], trades = [], lastAnalysis } = snapshot.state;
  const protection = snapshot.state.protection || {}, protectionLabel = protection.waitingForFreshQuote ? 'PROTECCIONES ESPERANDO FEED' : protection.protectedPositions ? 'PROTECCIONES ARMADAS' : 'SIN PROTECCIONES';
  const automation = snapshot.state.automation || {}, automationLabel = automation.status === 'starting' ? 'INICIANDO' : automation.status === 'running' ? 'EJECUTANDO' : automation.status === 'paused' ? 'PAUSADO' : automation.status === 'completed-with-errors' ? 'ERROR' : automation.status === 'interrupted' ? 'INTERRUMPIDO' : 'EN ESPERA';
  const benchmarkReady = Number(snapshot.state.benchmark?.startPrice) > 0 && Number(snapshot.state.benchmark?.currentPrice) > 0, benchmarkReturn = benchmarkReady && Number.isFinite(Number(snapshot.state.benchmark?.buyAndHoldReturnPct)) ? Number(snapshot.state.benchmark.buyAndHoldReturnPct) : null;
  const invested = positions.reduce((sum, item) => sum + item.quantity * (item.mark || item.entry), 0);
  const initialCash = Number(snapshot.state.initialCash) || 100;
  const portfolioValue = Number(cash) + invested;
  const pnl = portfolioValue - initialCash;
  const peak = Number(snapshot.state.peakEquity) || initialCash;
  const drawdown = peak ? Math.max(0, (peak - portfolioValue) / peak * 100) : 0;
  const history = snapshot.state.equityHistory?.length ? snapshot.state.equityHistory : [{ value: initialCash, time: new Date().toISOString() }];
  const equityValues = history.map(item => Number(item.value) || initialCash);
  const drawdownValues = equityValues.map((value, index) => { const high = Math.max(...equityValues.slice(0, index + 1)); return high ? ((high - value) / high) * 100 : 0; });
  const maxDrawdown = Math.max(0, ...drawdownValues);
  const closedTrades = trades.filter(item => item.side === 'SELL' && item.realizedPnl != null && Number.isFinite(Number(item.realizedPnl)));
  const wins = closedTrades.filter(item => Number(item.realizedPnl) > 0).length;
  const winRate = closedTrades.length ? wins / closedTrades.length * 100 : 0;
  $('#page').innerHTML = `
    <div class="notice"><strong>Paper realtime:</strong> los precios vienen del mercado, pero las órdenes no salen de esta aplicación. La cuenta se actualiza con cada tick y aplica costes simulados. <span class="tag ${snapshot.settings.automationEnabled ? '' : 'sell'}">${snapshot.settings.automationEnabled ? 'AUTO-PAPER ACTIVO' : 'AUTO-PAPER PAUSADO'}</span>${snapshot.state.automation?.lastError ? `<br><span class="negative">Último error del automatizador: ${esc(snapshot.state.automation.lastError)}</span>` : ''}</div>
    <div class="grid metrics">
      <div class="card metric"><small>VALOR DE CUENTA</small><strong class="blue">${money(portfolioValue)}</strong><span class="subtle">Inicio: ${money(initialCash)}</span></div>
      <div class="card metric"><small>P&amp;L NETO</small><strong class="${pnl >= 0 ? 'green' : 'negative'}">${pnl >= 0 ? '+' : ''}${money(pnl)}</strong><span class="subtle">${initialCash ? (pnl / initialCash * 100).toFixed(2) : '0.00'}%</span></div>
      <div class="card metric"><small>POSICIONES ABIERTAS</small><strong class="green">${positions.length}</strong></div>
      <div class="card metric"><small>DRAWDOWN ACTUAL</small><strong class="${drawdown > 0 ? 'negative' : 'amber'}">${drawdown.toFixed(2)}%</strong></div>
      <div class="card metric"><small>BUY &amp; HOLD BTC</small><strong class="${benchmarkReturn == null ? 'amber' : benchmarkReturn >= 0 ? 'green' : 'negative'}">${benchmarkReturn == null ? 'N/D' : `${benchmarkReturn >= 0 ? '+' : ''}${benchmarkReturn.toFixed(2)}%`}</strong><span class="subtle">Cuenta sin operar</span></div>
    </div>
    <div class="grid dashboard-grid">
      <section class="card chart-card"><div class="card-header"><div><p class="section-kicker">PERFORMANCE</p><h2>Curva de equity</h2><p>Valor de la cuenta actualizado en tiempo real</p></div><div class="card-tools"><span class="tag">LIVE</span><span class="chart-legend"><i class="legend-line"></i>Equity</span></div></div>${lineChart(equityValues, 'equity')}<div class="chart-foot"><span>Inicio ${money(initialCash)}</span><span>Ahora ${money(portfolioValue)}</span></div></section>
      <section class="card chart-card"><div class="card-header"><div><p class="section-kicker">RISK</p><h2>Drawdown</h2><p>Caída desde el máximo de la cuenta</p></div><span class="tag ${maxDrawdown > 0 ? 'sell' : ''}">${maxDrawdown.toFixed(2)}% MAX</span></div>${lineChart(drawdownValues, 'drawdown', true)}<div class="perf-grid"><div class="perf-item"><span class="stat-label">REALIZADO</span><strong class="${Number(snapshot.state.realizedPnl) >= 0 ? 'positive' : 'negative'}">${money(snapshot.state.realizedPnl)}</strong></div><div class="perf-item"><span class="stat-label">WIN RATE</span><strong>${winRate.toFixed(0)}%</strong></div></div></section>
    </div>
    <div class="grid dashboard-grid" style="margin-top:16px"><section class="card"><div class="card-header"><div><p class="section-kicker">PORTFOLIO</p><h2>Posiciones abiertas</h2><p>Exposición valorada al último precio</p></div><button class="btn primary" id="goAnalyze">＋ Analizar</button></div>${renderPositions(positions)}</section><section class="card"><div class="card-header"><div><p class="section-kicker">ALLOCATION</p><h2>Distribución</h2><p>Cash frente a capital invertido</p></div></div>${allocationChart(cash, invested, portfolioValue)}</section></div>
    <section class="card table-card"><div class="card-header"><div><p class="section-kicker">AUDIT LOG</p><h2>Actividad reciente</h2><p>Órdenes simuladas y resultados registrados</p></div><button class="btn secondary" id="goSettings">Parámetros</button></div>${renderTrades(trades)}</section>`;
  $('#page').insertAdjacentHTML('afterbegin', renderAlerts(snapshot.state.alerts || []));
  $('#page').insertAdjacentHTML('afterbegin', `<div class="notice"><strong>Protección:</strong> ${protectionLabel}${protection.waitingForFreshQuote ? ' · no se inventan fills mientras el feed esté offline' : ''}</div>`);
  $('#page').insertAdjacentHTML('afterbegin', `<div class="notice"><strong>Auto-Paper:</strong> ${automationLabel}${automation.heartbeatAt ? ` · heartbeat ${time(automation.heartbeatAt)}` : ''}${automation.durationMs != null ? ` · última corrida ${Number(automation.durationMs)} ms` : ''}</div>`);
  $('#page').insertAdjacentHTML('afterbegin', renderAutomationActivity(automation.progress || []));
  $('#goAnalyze').onclick = () => navigate('analyze');
  $('#goSettings').onclick = () => navigate('settings');
}

function lineChart(values, kind = 'equity', inverse = false) {
  const width = 760, height = 214, padX = 8, padTop = 14, padBottom = 24;
  const data = values.length > 1 ? values : [values[0] || 0, values[0] || 0];
  const min = inverse ? 0 : Math.min(...data), max = inverse ? Math.max(1, ...data) : Math.max(...data), range = max - min || 1;
  const points = data.map((value, index) => { const x = padX + index * (width - padX * 2) / (data.length - 1); const y = padTop + (max - value) / range * (height - padTop - padBottom); return [x, y]; });
  const path = points.map(([x, y], index) => `${index ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');
  const area = `${path} L${points.at(-1)[0].toFixed(1)} ${height - padBottom} L${points[0][0].toFixed(1)} ${height - padBottom} Z`, stroke = inverse ? '#f47f91' : '#57d7cf', id = `${kind}Fill`;
  return `<svg class="svg-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Gráfico de ${kind === 'equity' ? 'equity' : 'drawdown'}"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${stroke}" stop-opacity=".28"/><stop offset="1" stop-color="${stroke}" stop-opacity="0"/></linearGradient></defs>${[.25,.5,.75].map(level => `<line class="chart-gridline" x1="${padX}" x2="${width-padX}" y1="${(padTop+level*(height-padTop-padBottom)).toFixed(1)}" y2="${(padTop+level*(height-padTop-padBottom)).toFixed(1)}"/>`).join('')}<path class="chart-area" d="${area}" style="fill:url(#${id})"/><path class="chart-line" d="${path}" style="stroke:${stroke}"/><circle class="chart-point" cx="${points.at(-1)[0]}" cy="${points.at(-1)[1]}" style="stroke:${stroke}" r="4"/><text class="chart-axis" x="${padX}" y="${height-5}">${kind === 'equity' ? money(min) : '0%'}</text><text class="chart-axis" x="${width-padX}" y="${height-5}" text-anchor="end">${kind === 'equity' ? money(max) : max.toFixed(1)+'%'}</text></svg>`;
}

function allocationChart(cash, invested, total) {
  const safeTotal = total > 0 ? total : 1, investedPct = Math.max(0, Math.min(100, invested / safeTotal * 100)), circumference = 2 * Math.PI * 46, dash = circumference * investedPct / 100;
  return `<div class="donut-wrap"><svg class="donut" viewBox="0 0 132 132"><circle class="donut-base" cx="66" cy="66" r="46"/><circle class="donut-segment" cx="66" cy="66" r="46" style="--dash:${dash} ${circumference};--offset:0"/><text class="donut-center" x="66" y="70">${investedPct.toFixed(0)}%</text></svg><div class="allocation-legend"><div class="allocation-row"><span><i class="allocation-bullet"></i>Invertido</span><b>${money(invested)}</b></div><div class="allocation-row"><span><i class="allocation-bullet cash"></i>Cash</span><b>${money(cash)}</b></div><div class="allocation-row"><span>Cuenta total</span><b>${money(total)}</b></div></div></div>`;
}

function renderPositions(positions) {
  if (!positions.length) return '<div class="empty">No hay posiciones abiertas. Elige un mercado para empezar a investigar.</div>';
  return `<table class="table"><thead><tr><th>ACTIVO</th><th>CANTIDAD</th><th>COSTE MEDIO</th><th>BID</th><th>PROTECCIÓN</th><th>P&amp;L ABIERTO</th><th>ACCIÓN</th></tr></thead><tbody>${positions.map(item => { const mark = item.bid || item.mark || item.entry; const pnl = (mark - item.entry) * item.quantity; const protection=[item.stopLoss?`SL ${money(item.stopLoss)}`:'',item.takeProfit?`TP ${money(item.takeProfit)}`:''].filter(Boolean).join(' · ')||'Sin protección'; return `<tr><td class="symbol-cell"><strong>${esc(item.symbol)}</strong><small>${time(item.markAt)}</small></td><td>${qty(item.quantity)}</td><td>${money(item.entry)}</td><td>${money(mark)}</td><td class="subtle">${protection}</td><td class="${pnl >= 0 ? 'positive' : 'negative'}">${money(pnl)}</td><td><button class="table-action" data-close-position="${esc(item.symbol)}">Reducir / cerrar</button></td></tr>`; }).join('')}</tbody></table>`;
}

function renderTrades(trades) {
  if (!trades.length) return '<div class="empty">No hay trades todavía.</div>';
  return `<table class="table"><thead><tr><th>ACTIVO</th><th>TIPO</th><th>PRECIO</th><th>COSTE</th><th>FECHA</th></tr></thead><tbody>${trades.slice(0, 8).map(item => `<tr><td class="symbol-cell"><strong>${esc(item.symbol)}</strong><small>${esc(item.source || 'manual')}</small></td><td><span class="tag ${item.side === 'SELL' ? 'sell' : 'buy'}">${esc(item.side)}</span></td><td>${qty(item.quantity)} @ ${money(item.price)}</td><td>${money(item.fee || 0)}</td><td>${time(item.createdAt)}</td></tr>`).join('')}</tbody></table>`;
}

function renderOrders(orders) {
  if (!orders?.length) return '<div class="empty">No hay órdenes registradas.</div>';
  return `<table class="table"><thead><tr><th>ACTIVO</th><th>TIPO</th><th>ESTADO</th><th>EJECUTADO / TOTAL</th><th>FECHA</th><th>ACCIÓN</th></tr></thead><tbody>${orders.slice(0, 100).map(order => `<tr><td class="symbol-cell"><strong>${esc(order.symbol)}</strong><small>${esc(order.source || 'manual')}</small></td><td>${esc(order.side)} ${esc(order.type || '')}</td><td><span class="tag">${esc(order.status || 'unknown')}</span><small>${esc(order.reason||order.failureReason||'')}</small></td><td>${qty(order.filledQuantity ?? 0)} / ${qty(order.quantity)}<small class="subtle">Reserva ${money(order.reservedCash||0)}</small></td><td>${time(order.filledAt || order.createdAt)}</td><td>${['created','accepted','partial'].includes(order.status) ? `<button class="table-action" data-cancel-order="${esc(order.id)}">Cancelar</button>` : '—'}</td></tr>`).join('')}</tbody></table>`;
}

function dailyPnlChart(points = []) {
  if (!points.length) return '<div class="daily-pnl empty">Aún no hay suficientes datos diarios.</div>';
  const visible = points.slice(-14), max = Math.max(0.01, ...visible.map(item => Math.abs(Number(item.pnl) || 0)));
  return `<div class="daily-pnl"><div class="daily-pnl-head"><h3>P&amp;L diario</h3><span>últimos ${visible.length} días</span></div><div class="daily-bars">${visible.map(item => { const pnl = Number(item.pnl) || 0, height = Math.max(4, Math.abs(pnl) / max * 100); return `<div class="daily-bar"><span class="daily-bar-value ${pnl >= 0 ? 'positive' : 'negative'}">${pnl >= 0 ? '+' : ''}${money(pnl)}</span><i class="${pnl >= 0 ? 'up' : 'down'}" style="height:${height}%"></i><small>${esc(item.date.slice(5))}</small></div>`; }).join('')}</div></div>`;
}
function renderStatistics(data, rangeDays = 'all', showRange = false) {
  const stats = computeTradingStats(data, rangeDays), card = (label, value, kind = '') => `<div><small>${label}</small><strong class="${kind}">${value}</strong></div>`, pct = value => value == null ? 'N/D' : `${value >= 0 ? '+' : ''}${value.toFixed(2)}%`, num = value => value == null ? 'N/D' : value.toFixed(2), rangeToolbar = showRange ? `<div class="stats-range"><label for="statsRange">Rango</label><select id="statsRange"><option value="1" ${rangeDays === 1 ? 'selected' : ''}>24 horas</option><option value="7" ${rangeDays === 7 ? 'selected' : ''}>7 días</option><option value="30" ${rangeDays === 30 ? 'selected' : ''}>30 días</option><option value="all" ${rangeDays === 'all' ? 'selected' : ''}>Todo</option></select></div>` : '';
  const items=[['EQUITY',money(stats.current)],['RETORNO DEL PERIODO',pct(stats.returnPct)],['P&L REALIZADO BRUTO',money(stats.grossPnl)],['P&L REALIZADO NETO',money(stats.netPnl)],['API · SESIÓN (USD)',money(stats.llmCost)],['BENCHMARK · SESIÓN',pct(stats.benchmarkReturn)],['DIFERENCIA VS BTC',pct(stats.alpha)],['HOY · UTC',pct(stats.returnToday)],['7 DÍAS',pct(stats.return7)],['30 DÍAS',pct(stats.return30)],['ÓRDENES DE SALIDA',String(stats.trades)],['WIN RATE',pct(stats.winRate)],['DRAWDOWN MÁXIMO',pct(stats.maxDrawdown)],['EXPOSICIÓN MÁXIMA',pct(stats.maxExposurePct)],['COMISIONES',money(stats.fees)],['VOLUMEN OPERADO',money(stats.turnover)],['PROFIT FACTOR NETO',num(stats.profitFactor)],['EXPECTATIVA NETA',stats.expectancy==null?'N/D':money(stats.expectancy)],['VOLATILIDAD',pct(stats.volatility)],['SHARPE',num(stats.sharpe)],['SORTINO',num(stats.sortino)],['DESPUÉS DE API',pct(stats.netAfterLlmPct)]];
  return `${rangeToolbar}<div class="stat-cards">${items.map(([label,value])=>card(label,value)).join('')}</div><div class="stats-chart-row"><section><h3>Equity</h3>${lineChart(stats.history,'equity')}</section><section><h3>Drawdown</h3>${lineChart(stats.drawdowns,'drawdown',true)}</section></div>${dailyPnlChart(stats.dailyPnl)}<p class="stat-foot">Fees incluidos en P&L neto. API acumulada en USD; resultado después de API disponible solo con cuenta USD. Benchmark de sesión disponible en rango Todo. Sharpe y Sortino requieren 30 observaciones diarias completas; cierres parciales agrupados por orden.</p>`;
}

function renderBars(confidence) {
  const level = Math.max(1, Math.round((Number(confidence) || 0) / 10));
  return Array.from({ length: 18 }, (_, index) => `<i class="bar" style="height:${index < level ? 35 + index * 6 : 5}%"></i>`).join('');
}

function renderAnalyze() {
  $('#page').innerHTML = `
    <div class="notice"><strong>Flujo recomendado:</strong> mercado público → análisis del LLM → revisión humana → ejecución paper. Una integración con un broker real queda fuera de esta V1.</div>
    <section class="card form-card"><div class="section-head"><div><h2>Nuevo análisis</h2><p>El modelo recibirá las últimas 60 velas OHLCV.</p></div><span class="mode-pill" style="margin:0">PAPER ONLY</span></div>
      <div class="form-row"><div class="field"><label for="symbol">Símbolo</label><input id="symbol" value="BTCUSDT" spellcheck="false"></div><div class="field"><label for="interval">Intervalo</label><select id="interval"><option value="15m">15 minutos</option><option value="1h" selected>1 hora</option><option value="4h">4 horas</option><option value="1d">1 día</option></select></div><div class="field"><label for="quantity">Cantidad paper</label><input id="quantity" type="number" min="0.00000001" step="any" value="0.0001"></div></div>
      <div class="actions"><button class="btn primary" id="runAnalysis">Ejecutar análisis</button><span class="subtle" id="analysisStatus"></span></div>
    </section>
    <section id="analysisResult"></section>`;
  $('#runAnalysis').onclick = runAnalysis;
  if (analysis) drawAnalysis(analysis);
}

async function runAnalysis() {
  const button = $('#runAnalysis'), status = $('#analysisStatus');
  button.disabled = true; status.textContent = 'Consultando mercado y LLM…';
  try { const symbol = $('#symbol').value.trim().toUpperCase(); const interval = $('#interval').value; subscribeSymbols([symbol]); [analysis, marketData] = await Promise.all([window.traderAPI.analyze({ symbol, interval }), window.traderAPI.loadMarket({ symbol, interval })]); snapshot.state.lastAnalysis = analysis; drawAnalysis(analysis); status.textContent = 'Listo'; }
  catch (error) { status.textContent = ''; toast(error.message); }
  finally { button.disabled = false; }
}

function drawAnalysis(result) {
  const risks = Array.isArray(result.riskNotes) ? result.riskNotes : [];
  const prices = marketData?.candles?.map(candle => Number(candle.close)).filter(Number.isFinite) || [];
  const trace = Array.isArray(result.agentTrace) ? result.agentTrace : [], headlines = Array.isArray(result.news) ? result.news : [], consensus = result.consensus || {}, critical = result.criticalAgent || {}, portfolio = result.portfolioAgent || {}, quality = result.dataQuality || {}, qualityBox = `<span class="tag ${quality.status === 'degraded' ? 'amber' : quality.status === 'invalid' ? 'sell' : ''}">DATOS ${esc(String(quality.status || 'desconocidos').toUpperCase())}</span>`;
  const consensusBox = `<div class="consensus-box"><div><small>DECISIÓN AGREGADA</small><strong class="decision-inline ${esc(consensus.decision || result.decision)}">${esc(consensus.decision || result.decision)}</strong><span>${Number(consensus.confidence ?? result.confidence) || 0}% confianza · ${Number(consensus.agreement || 0)} agentes alineados</span></div><p>${esc(consensus.rationale || 'La intención pasa a revisión del motor de riesgo.')}</p>${(critical.issues || []).concat(portfolio.issues || []).length ? `<ul>${(critical.issues || []).concat(portfolio.issues || []).map(item => `<li>${esc(item)}</li>`).join('')}</ul>` : ''}</div>`;
  $('#analysisResult').innerHTML = `<section class="card analysis-card"><div class="analysis-top"><div><p class="section-kicker">MARKET SNAPSHOT</p><h2>${esc(result.symbol)} <span class="subtle">· ${esc(result.interval)}</span></h2><p class="subtle">Precio de referencia ${money(result.price)} · ${time(result.createdAt)}</p></div><div class="analysis-badges">${qualityBox}<span class="decision ${esc(result.decision)}">${esc(result.decision)}</span></div></div>${prices.length ? `<div class="market-chart">${lineChart(prices, 'equity')}</div>` : ''}<div class="agent-trace">${trace.map(agent => `<span class="trace-${esc(agent.status)}"><i></i>${esc(agent.name)}<small>${esc(agent.detail)}</small></span>`).join('')}</div>${consensusBox}${headlines.length ? `<div class="news-context"><div class="news-title">Titulares usados <span>${esc(result.newsAgent?.sentiment || 'neutral')}</span></div>${headlines.slice(0,4).map(item => `<a href="${esc(item.link)}" target="_blank" rel="noreferrer">${esc(item.title)}<small>${esc(item.source)} · ${esc(item.publishedAt || 'fecha desconocida')}</small></a>`).join('')}</div>` : '<div class="news-empty">Sin titulares relevantes disponibles para este análisis.</div>'}<div class="analysis-grid"><div class="analysis-stat"><small>CONFIANZA</small><strong>${Number(result.confidence) || 0}%</strong></div><div class="analysis-stat"><small>ENTRADA SUGERIDA</small><strong>${money(result.entry)}</strong></div><div class="analysis-stat"><small>STOP / TAKE PROFIT</small><strong>${money(result.stopLoss)} / ${money(result.takeProfit)}</strong></div></div><p class="thesis">${esc(result.thesis)}</p>${risks.length ? `<ul class="risk-list">${risks.map(risk => `<li>${esc(risk)}</li>`).join('')}</ul>` : ''}<div class="actions">${result.decision === 'BUY' || result.decision === 'SELL' ? '<button class="btn primary" id="executeTrade">Confirmar orden paper</button>' : ''}<button class="btn" id="backDashboard">Volver al dashboard</button></div></section>`;
  $('#backDashboard').onclick = () => navigate('dashboard');
  $('#executeTrade')?.addEventListener('click', executeTrade);
}

async function executeTrade() {
  const side = analysis.decision, quantity = Number($('#quantity').value), price = Number(analysis.entry || analysis.price);
  if (!confirm(`¿Confirmar ${side} paper de ${quantity} ${analysis.symbol} a ${money(price)}?`)) return;
  try { snapshot.state = await window.traderAPI.executePaper({ symbol: analysis.symbol, side, quantity, price, stopLoss: analysis.stopLoss, takeProfit: analysis.takeProfit, source: 'llm-analysis', clientOrderId: `llm-${analysis.symbol}-${Date.parse(analysis.createdAt) || Date.now()}` }); subscribeSymbols([analysis.symbol]); toast('Orden paper ejecutada'); renderDashboard(); }
  catch (error) { toast(error.message); }
}

function renderLive() {
  $('#page').innerHTML=`<div class="notice"><strong>Real · solo lectura:</strong> puedes verificar una cuenta de Binance y leer sus saldos. El envío y cancelación de órdenes están bloqueados en esta versión.</div><section class="card settings-card"><div class="card-header"><div><p class="section-kicker">BROKER CONNECTION</p><h2>Cuenta Binance</h2><p>Usa primero testnet o demo. Estas credenciales son independientes de la API key del LLM.</p></div><span class="tag">READ ONLY</span></div><div class="form-row"><div class="field"><label for="brokerEnvironment">Entorno</label><select id="brokerEnvironment"><option value="testnet">Spot Testnet</option><option value="demo">Demo Trading</option><option value="mainnet">Mainnet · lectura</option></select></div><div class="field"><label for="brokerApiKey">API key del broker</label><input id="brokerApiKey" type="password" placeholder="No se muestra después de guardarla"></div><div class="field"><label for="brokerSecret">Secret del broker</label><input id="brokerSecret" type="password" placeholder="Se guarda cifrado localmente"></div></div><div class="actions"><button class="btn" id="saveBroker">Guardar credenciales</button><button class="btn primary" id="testBroker">Probar cuenta</button><button class="btn" id="preflightLive">Evaluar preflight</button><button class="btn" id="armSandbox">Armar sandbox · 15 min</button><button class="btn" id="killSandbox">Kill switch sandbox</button><span id="brokerStatus" class="subtle"></span></div></section><section id="brokerResult" class="card settings-card" style="margin-top:16px"><h2>Estado de conexión</h2><p class="thesis">Aún no se ha probado ninguna cuenta.</p></section>`;
  $('#brokerEnvironment').value=snapshot.settings.brokerEnvironment||'testnet';
  updateBrokerStatus(snapshot.broker);
  $('#page').insertAdjacentHTML('beforeend', `<section id="sandboxExecution" class="card settings-card" style="margin-top:16px"><div class="card-header"><div><p class="section-kicker">SANDBOX</p><h2>Probar una orden del proveedor</h2><p>Solo testnet/demo. Esta orden no usa el ledger paper y mainnet permanece bloqueado.</p></div><span class="tag">TESTNET / DEMO</span></div><div class="form-row"><div class="field"><label for="sandboxSymbol">Símbolo</label><input id="sandboxSymbol" value="BTCUSDT"></div><div class="field"><label for="sandboxSide">Lado</label><select id="sandboxSide"><option>BUY</option><option>SELL</option></select></div><div class="field"><label for="sandboxType">Tipo</label><select id="sandboxType"><option value="MARKET">MARKET</option><option value="LIMIT">LIMIT</option></select></div></div><div class="form-row"><div class="field"><label for="sandboxQuantity">Cantidad</label><input id="sandboxQuantity" type="number" min="0" step="any" value="0.001"></div><div class="field" id="sandboxPriceWrap"><label for="sandboxPrice">Precio límite</label><input id="sandboxPrice" type="number" min="0" step="any"></div></div><div class="actions"><button class="btn primary" id="placeSandbox">Enviar orden sandbox</button><span id="sandboxStatus" class="subtle"></span></div><div id="sandboxOrderResult" class="subtle" style="margin-top:12px"></div></section>`);
  const updateSandboxForm=()=>{const sandbox=$('#brokerEnvironment').value!=='mainnet',armed=Boolean(snapshot.broker?.sandboxArmedUntil&&Date.now()<new Date(snapshot.broker.sandboxArmedUntil).getTime());$('#sandboxExecution').style.opacity=sandbox?'1':'.55';$('#placeSandbox').disabled=!sandbox||!armed;$('#killSandbox').disabled=!sandbox||!armed;$('#armSandbox').disabled=!sandbox;$('#sandboxPriceWrap').style.display=$('#sandboxType').value==='LIMIT'?'block':'none';};
  $('#brokerEnvironment').onchange=updateSandboxForm; $('#sandboxType').onchange=updateSandboxForm; updateSandboxForm();
  $('#placeSandbox').onclick=async()=>{if(!confirm('¿Enviar esta orden al entorno sandbox seleccionado?'))return;const status=$('#sandboxStatus');status.textContent='Enviando…';try{const result=await window.traderAPI.placeSandboxOrder({symbol:$('#sandboxSymbol').value,side:$('#sandboxSide').value,type:$('#sandboxType').value,quantity:Number($('#sandboxQuantity').value),price:Number($('#sandboxPrice').value)||undefined,confirmSandbox:true});$('#sandboxOrderResult').textContent=`Orden ${result.orderId||result.clientOrderId||'recibida'} · estado ${result.status||'aceptada'}`;status.textContent='OK';}catch(error){status.textContent='';toast(error.message);}};
  $('#killSandbox').onclick=async()=>{if(!confirm('¿Cancelar todas las órdenes pendientes del entorno sandbox?'))return;const status=$('#brokerStatus');status.textContent='Cancelando pendientes…';try{const result=await window.traderAPI.killSandbox();snapshot.broker=result.broker;status.textContent=`${result.cancelled} canceladas · ${result.failed} fallidas`;updateBrokerStatus(result.broker);updateSandboxForm();toast('Kill switch sandbox ejecutado');}catch(error){status.textContent='';toast(error.message);}};
  $('#armSandbox').onclick=async()=>{if(!confirm('¿Armar sandbox durante 15 minutos? Solo testnet/demo y nunca mainnet.'))return;const status=$('#brokerStatus');status.textContent='Armando sandbox…';try{const result=await window.traderAPI.armSandbox();snapshot.broker={...(snapshot.broker||{}),sandboxArmedUntil:result.expiresAt};updateSandboxForm();status.textContent=`Armado hasta ${time(result.expiresAt)}`;toast('Sandbox armado temporalmente');}catch(error){status.textContent='';toast(error.message);}};
  $('#preflightLive').onclick=async()=>{const status=$('#brokerStatus');status.textContent='Evaluando preflight…';try{const result=await window.traderAPI.brokerPreflight();const target=$('#brokerResult');target.innerHTML=`<h2>Preflight ${result.readyForSandbox?'apto para sandbox':'no apto para sandbox'}</h2><p class="subtle">Live real: bloqueado por diseño · Evaluado ${time(result.evaluatedAt)}</p><div class="preflight-list">${result.checks.map(check=>`<div class="preflight-check ${check.ok?'ok':'fail'}"><i></i><strong>${esc(check.label)}</strong><span>${esc(check.detail)}</span></div>`).join('')}</div>`;status.textContent=result.readyForSandbox?'SANDBOX OK':'Revisar requisitos';}catch(error){status.textContent='';toast(error.message);}};
  $('#saveBroker').onclick=async()=>{try{await window.traderAPI.saveBrokerCredentials({environment:$('#brokerEnvironment').value,apiKey:$('#brokerApiKey').value,secret:$('#brokerSecret').value});$('#brokerApiKey').value='';$('#brokerSecret').value='';toast('Credenciales guardadas cifradas');}catch(error){toast(error.message);}};
  $('#testBroker').onclick=async()=>{const status=$('#brokerStatus');status.textContent='Consultando cuenta y órdenes…';try{const result=await window.traderAPI.testBrokerConnection();$('#brokerResult').innerHTML=`<h2>Cuenta conectada</h2><p class="thesis">Entorno: <strong>${esc(result.environment)}</strong> · Tipo: <strong>${esc(result.accountType||'—')}</strong> · Balances con saldo: <strong>${result.balanceCount}</strong> · Órdenes abiertas: <strong>${result.openOrderCount}</strong></p><p class="subtle">Trading live habilitado por el proveedor: ${result.canTrade?'sí':'no'} · Envío desde esta app: bloqueado</p>`;status.textContent='OK';}catch(error){status.textContent='';toast(error.message);}};
}

function renderBrokerOrders(orders = []) {
  if (!orders.length) return '<p class="subtle">No hay órdenes del broker registradas.</p>';
  return `<div class="broker-orders"><h3>Órdenes normalizadas</h3><table class="table"><thead><tr><th>SÍMBOLO</th><th>LADO</th><th>ESTADO</th><th>CANTIDAD</th><th>ACTUALIZADA</th></tr></thead><tbody>${orders.slice(0, 12).map(order => `<tr><td>${esc(order.symbol || '—')}</td><td><span class="tag ${order.side === 'SELL' ? 'sell' : 'buy'}">${esc(order.side || '—')}</span></td><td>${esc(order.status || '—')}</td><td>${esc(order.executedQuantity || order.quantity || '0')} / ${esc(order.quantity || order.origQty || '0')}</td><td>${time(order.transactTime || order.eventTime || order.updatedAt || order.eventAt)}</td></tr>`).join('')}</tbody></table></div>`;
}

function renderBrokerBalances(balances = []) {
  if (!balances.length) return '<p class="subtle">No hay balances con saldo.</p>';
  return `<div class="broker-balances"><h3>Balances normalizados</h3><table class="table"><thead><tr><th>ACTIVO</th><th>LIBRE</th><th>BLOQUEADO</th><th>TOTAL</th></tr></thead><tbody>${balances.slice(0, 20).map(balance => `<tr><td><strong>${esc(balance.asset || '—')}</strong></td><td>${Number(balance.free || 0).toLocaleString('en-US', { maximumFractionDigits: 8 })}</td><td>${Number(balance.locked || 0).toLocaleString('en-US', { maximumFractionDigits: 8 })}</td><td><strong>${Number(balance.total || 0).toLocaleString('en-US', { maximumFractionDigits: 8 })}</strong></td></tr>`).join('')}</tbody></table></div>`;
}

function updateBrokerStatus(broker) {
  const target=$('#brokerResult'); if(!target||!broker)return;
  const audit = broker.audit ? `<p class="subtle">Auditoría: broker ${broker.audit.brokerEvents?.valid === false ? '<span class="negative">inválida</span>' : 'íntegra'} · ledger ${broker.audit.liveLedger?.valid === false ? '<span class="negative">inválido</span>' : 'íntegro'}</p>` : '', recovery = broker.recovery?.attempted ? `<p class="subtle">Recuperación: ${broker.recovery.recovered} resueltas · ${broker.recovery.unresolved} sin resolver${broker.recovery.unresolved ? ' · revisa antes de operar' : ''}</p>` : '';
  if(broker.status==='connected'&&broker.account) target.innerHTML=`<h2>Cuenta conectada</h2><p class="thesis">Entorno: <strong>${esc(broker.account.environment)}</strong> · Tipo: <strong>${esc(broker.account.accountType||'—')}</strong> · Balances con saldo: <strong>${broker.account.balances.length}</strong> · Órdenes abiertas: <strong>${broker.openOrders.length}</strong></p><p class="subtle">Trading live habilitado por el proveedor: ${broker.account.canTrade?'sí':'no'} · Envío desde esta app: bloqueado · Stream: ${esc(broker.stream||'desconectado')} · Última sincronización: ${time(broker.lastSyncAt)}</p>${broker.discrepancies?.length?`<p class="negative">Discrepancias detectadas: ${broker.discrepancies.length}. Revisa la cuenta antes de operar.</p>`:''}${recovery}${audit}${renderBrokerBalances(broker.account.balances)}${renderBrokerOrders(broker.orders || broker.openOrders || [])}`;
  else if(broker.status==='error') target.innerHTML=`<h2>Broker desconectado</h2><p class="thesis negative">${esc(broker.error||'Error desconocido')}</p><p class="subtle">La sincronización se reintentará automáticamente.</p>`;
}

async function startAutomationFromUI(targetPage = 'dashboard') {
  const button = $('#runAutoPaper'); if (button) button.disabled = true;
  try { const result = await window.traderAPI.startPaperAutomation(); snapshot.state = result?.state || result; if (result?.started === false) { const failures = (result.preflight?.checks || []).filter(item => !item.ok).map(item => `${item.label}: ${item.detail}`).join(' | '); toast(`Auto-Paper no inició: ${failures || 'preflight rechazado'}`); render(); return; } snapshot.settings.automationEnabled = true; toast('Preflight correcto; Auto-Paper iniciado'); navigate(targetPage); }
  catch (error) { toast(error.message); }
  finally { $('#runAutoPaper')?.removeAttribute('disabled'); }
}

function openAutomationStartModal(targetPage = page) {
  $('#automationStartModal')?.remove();
  const config = snapshot.settings || {}, symbols = (config.automationSymbols || ['BTCUSDT']).join(', ');
  document.body.insertAdjacentHTML('beforeend', `<div class="modal-backdrop" id="automationStartModal"><form class="start-modal" id="automationStartForm"><div class="modal-header"><div><p class="section-kicker">AUTO-PAPER PREFLIGHT</p><h2>Iniciar agentes</h2><p>Revisa la configuración antes de activar análisis y ejecución paper.</p></div><button type="button" class="modal-close" id="closeAutomationModal" aria-label="Cerrar">×</button></div><div class="modal-grid"><div class="field model-picker"><label for="startModel">Modelo del analista</label><select id="startModel">${modelOptions(config.model || 'gpt-5.6-luna')}</select><input id="startCustomModel" value="${esc(MODEL_CATALOG.some(item => item.id === config.model) ? '' : config.model || '')}" placeholder="Identificador del modelo" hidden></div><div class="field"><label for="startSymbols">Símbolos</label><input id="startSymbols" value="${esc(symbols)}" placeholder="BTCUSDT, ETHUSDT"></div><div class="field"><label for="startTimeframe">Timeframe de análisis</label><select id="startTimeframe"><option value="15m">15 minutos</option><option value="1h">1 hora</option><option value="4h">4 horas</option><option value="1d">1 día</option></select></div><div class="field"><label for="startInterval">Intervalo entre corridas (min)</label><input id="startInterval" type="number" min="5" step="5" value="${Number(config.automationIntervalMin) || 15}"></div><div class="field"><label for="startConfidence">Confianza mínima (%)</label><input id="startConfidence" type="number" min="0" max="100" value="${Number(config.minConfidence) || 60}"></div><div class="field"><label for="startRisk">Riesgo por operación (%)</label><input id="startRisk" type="number" min="0.1" max="5" step="0.1" value="${Number(config.riskPerTradePct) || 1}"></div><div class="field"><label for="startBudget">Presupuesto LLM diario</label><input value="$${Number(config.llmDailyBudgetUsd) || 0} · ${Number(config.llmDailyCallBudget) || 0} llamadas" disabled></div></div><div class="start-modal-note"><strong>Modo seguro:</strong> se usará exclusivamente la cuenta paper ${esc(snapshot.state.currency || config.accountCurrency || 'USDT')}. El motor de riesgo conserva la autoridad final.</div><label class="checkline modal-confirm"><input id="startConfirm" type="checkbox" required> Confirmo que quiero iniciar Auto-Paper con esta configuración.</label><div class="actions"><button type="button" class="btn" id="cancelAutomationModal">Cancelar</button><button type="submit" class="btn primary" id="confirmAutomationStart">Guardar e iniciar</button></div></form></div>`);
  $('#startTimeframe').value = ['15m', '1h', '4h', '1d'].includes(config.automationTimeframe) ? config.automationTimeframe : '15m';
  bindModelPicker('#startModel', '#startCustomModel');
  const close = () => $('#automationStartModal')?.remove();
  $('#closeAutomationModal').onclick = close; $('#cancelAutomationModal').onclick = close;
  $('#automationStartForm').onsubmit = async event => { event.preventDefault(); const button = $('#confirmAutomationStart'), model = chosenModel('#startModel', '#startCustomModel'), pricing = knownModelPricing(model); if (!model) { toast('Selecciona o escribe un modelo válido'); return; } button.disabled = true; try { snapshot.settings = await window.traderAPI.saveSettings({ ...snapshot.settings, model, ...(pricing ? { llmInputCostPer1kUsd: pricing.inputPer1k, llmOutputCostPer1kUsd: pricing.outputPer1k } : {}), automationEnabled: false, automationSymbols: $('#startSymbols').value, automationTimeframe: $('#startTimeframe').value, automationIntervalMin: $('#startInterval').value, minConfidence: $('#startConfidence').value, riskPerTradePct: $('#startRisk').value }); close(); await startAutomationFromUI(targetPage); } catch (error) { toast(error.message); button.disabled = false; } };
}

function renderSettings() {
  setTimeout(() => { if ($('#runAutoPaper')) $('#runAutoPaper').onclick = () => openAutomationStartModal('dashboard'); }, 0);
  const config = snapshot.settings, usage = snapshot.state.llmUsage || {};
  $('#page').innerHTML = `<section class="card settings-card"><div class="card-header"><div><p class="section-kicker">SYSTEM</p><h2>Conexión del LLM</h2><p>La clave nunca se expone al renderer ni se guarda en texto plano.</p></div><span class="tag">PAPER ONLY</span></div><div class="field"><label for="endpoint">Endpoint compatible con OpenAI</label><input id="endpoint" value="${esc(config.endpoint)}"></div><div class="field model-picker"><label for="model">Modelo</label><select id="model">${modelOptions(config.model || 'gpt-5.6-luna')}</select><input id="customModel" value="${esc(MODEL_CATALOG.some(item => item.id === config.model) ? '' : config.model || '')}" placeholder="Identificador del modelo" hidden><small class="subtle">Luna es el valor predeterminado por coste; puedes cambiarlo antes de iniciar.</small></div><div class="field"><label for="apiKey">API key ${snapshot.hasApiKey ? '· ya configurada' : ''}</label><input id="apiKey" type="password" placeholder="Pega una clave nueva para guardarla cifrada"></div><h3>Simulación</h3><div class="form-row"><div class="field"><label for="initialCash">Capital inicial ($)</label><input id="initialCash" type="number" min="1" step="1" value="${Number(config.initialCash) || 100}"></div><div class="field"><label for="feeRate">Comisión por lado (%)</label><input id="feeRate" type="number" min="0" step="0.01" value="${(Number(config.feeRate) * 100).toFixed(3)}"></div><div class="field"><label for="slippageBps">Slippage (bps)</label><input id="slippageBps" type="number" min="0" step="1" value="${Number(config.slippageBps) || 10}"></div></div><div class="form-row"><div class="field"><label for="maxOrderPct">Máximo por orden (%)</label><input id="maxOrderPct" type="number" min="1" max="100" value="${Number(config.maxOrderPct) || 25}"></div><div class="field"><label for="maxDrawdownPct">Corte por drawdown (%)</label><input id="maxDrawdownPct" type="number" min="1" max="100" value="${Number(config.maxDrawdownPct) || 10}"></div><div class="field"><label for="riskPerTradePct">Riesgo por trade (%)</label><input id="riskPerTradePct" type="number" min="0.1" max="5" step="0.1" value="${Number(config.riskPerTradePct) || 1}"></div></div><h3>Auto-Paper</h3><label class="checkline"><input id="automationEnabled" type="checkbox" ${config.automationEnabled ? 'checked' : ''}> Permitir que el LLM ejecute paper automáticamente</label><div class="form-row" style="margin-top:14px"><div class="field"><label for="automationSymbols">Símbolos separados por coma</label><input id="automationSymbols" value="${esc((config.automationSymbols || ['BTCUSDT']).join(', '))}"></div><div class="field"><label for="automationIntervalMin">Intervalo mínimo (min)</label><input id="automationIntervalMin" type="number" min="5" step="5" value="${Number(config.automationIntervalMin) || 15}"></div><div class="field"><label for="minConfidence">Confianza mínima (%)</label><input id="minConfidence" type="number" min="0" max="100" value="${Number(config.minConfidence) || 60}"></div></div><h3>Presupuesto y gobierno de agentes</h3><div class="form-row"><div class="field"><label for="llmDailyCallBudget">Llamadas LLM por día</label><input id="llmDailyCallBudget" type="number" min="1" max="1000" value="${Number(config.llmDailyCallBudget) || 24}"></div><div class="field"><label for="llmDailyBudgetUsd">Presupuesto LLM diario (USD)</label><input id="llmDailyBudgetUsd" type="number" min="0" step="0.01" value="${Number(config.llmDailyBudgetUsd) || 1}"></div><div class="field"><label for="llmFailurePauseThreshold">Fallos antes de pausar</label><input id="llmFailurePauseThreshold" type="number" min="1" max="20" value="${Number(config.llmFailurePauseThreshold) || 3}"></div></div><div class="form-row"><div class="field"><label for="llmInputCostPer1kUsd">Coste entrada / 1k tokens</label><input id="llmInputCostPer1kUsd" type="number" min="0" step="0.0001" value="${Number(config.llmInputCostPer1kUsd) || 0}"></div><div class="field"><label for="llmOutputCostPer1kUsd">Coste salida / 1k tokens</label><input id="llmOutputCostPer1kUsd" type="number" min="0" step="0.0001" value="${Number(config.llmOutputCostPer1kUsd) || 0}"></div><div class="field"><label>Uso de hoy</label><input value="${Number(usage.calls || 0)} llamadas · ${Number(usage.inputTokens || 0) + Number(usage.outputTokens || 0)} tokens · $${Number(usage.estimatedCostUsd || 0).toFixed(4)}" disabled></div></div><label class="checkline"><input type="checkbox" checked disabled> El modo real está desactivado en la V1</label><div class="actions"><button class="btn primary" id="saveSettings">Guardar configuración</button><button class="btn" id="resetPaper">Reiniciar simulación</button><button class="btn" id="openData">Abrir carpeta de datos</button></div></section><section class="card settings-card" style="margin-top:16px"><h2>Modo live</h2><p class="thesis">Bloqueado por diseño. Para activarlo se añadirá un broker independiente, credenciales separadas, permisos mínimos, reconciliación, kill switch y confirmación explícita de cuenta.</p></section>`;
  bindModelPicker('#model', '#customModel');
  $('#model')?.addEventListener('change', () => { const pricing = knownModelPricing(chosenModel('#model', '#customModel')); if (pricing) { $('#llmInputCostPer1kUsd').value = pricing.inputPer1k; $('#llmOutputCostPer1kUsd').value = pricing.outputPer1k; } });
  const simulationRow = $('#riskPerTradePct')?.closest('.form-row');
  if (simulationRow) { const currencyRow = document.createElement('div'); currencyRow.className = 'form-row currency-config'; currencyRow.innerHTML = `<div class="field"><label for="accountCurrency">Moneda de liquidación</label><select id="accountCurrency"><option value="USDT">USDT · cripto</option><option value="USD">USD · fiat</option><option value="USDC">USDC · cripto</option></select></div><div class="field"><label>Nota</label><input value="Los pares BTCUSDT se valoran en USDT" disabled></div>`; simulationRow.parentElement?.insertBefore(currencyRow, simulationRow); $('#accountCurrency').value = snapshot.state.currency || config.accountCurrency || 'USDT'; }
  if (simulationRow) { const field = document.createElement('div'); field.className = 'field'; field.innerHTML = `<label for="partialFillPct">Fill máximo por actualización (%)</label><input id="partialFillPct" type="number" min="1" max="100" step="1" value="${Number(config.partialFillPct) || 100}">`; simulationRow.appendChild(field); }
  if (simulationRow) { const riskRow = document.createElement('div'); riskRow.className = 'form-row risk-config'; riskRow.innerHTML = `<div class="field"><label for="maxExposurePct">Exposición total máxima (%)</label><input id="maxExposurePct" type="number" min="1" max="100" value="${Number(config.maxExposurePct) || 75}"></div><div class="field"><label for="maxAssetExposurePct">Exposición máxima por activo (%)</label><input id="maxAssetExposurePct" type="number" min="1" max="100" value="${Number(config.maxAssetExposurePct) || 35}"></div><div class="field"><label for="maxPortfolioRiskPct">Riesgo agregado de stops (%)</label><input id="maxPortfolioRiskPct" type="number" min="0.1" max="100" step="0.1" value="${Number(config.maxPortfolioRiskPct) || 3}"></div><div class="field"><label for="maxSpreadBps">Spread máximo (bps)</label><input id="maxSpreadBps" type="number" min="1" value="${Number(config.maxSpreadBps) || 50}"></div><div class="field"><label for="maxTradesPerDay">Máximo de fills diarios</label><input id="maxTradesPerDay" type="number" min="1" value="${Number(config.maxTradesPerDay) || 20}"></div><div class="field"><label for="maxDataAgeMs">Edad máxima del dato (ms)</label><input id="maxDataAgeMs" type="number" min="1000" value="${Number(config.maxDataAgeMs) || 15000}"></div>`; simulationRow.parentElement?.insertBefore(riskRow, simulationRow.nextElementSibling); }
  if (simulationRow) { const executionRow = document.createElement('div'); executionRow.className = 'form-row execution-config'; executionRow.innerHTML = `<div class="field"><label for="executionLatencyMs">Latencia simulada (ms)</label><input id="executionLatencyMs" type="number" min="0" max="600000" value="${Number(config.executionLatencyMs) || 0}"></div><div class="field"><label for="limitOrderTtlMin">Caducidad de limit (min)</label><input id="limitOrderTtlMin" type="number" min="1" max="10080" value="${Number(config.limitOrderTtlMin) || 60}"></div><div class="field"><label for="liquidityNotionalPerTick">Liquidez por tick (USD)</label><input id="liquidityNotionalPerTick" type="number" min="0" step="1" value="${Number(config.liquidityNotionalPerTick) || 0}"></div><div class="field"><label for="backtestSpreadBps">Spread del backtest (bps)</label><input id="backtestSpreadBps" type="number" min="0" max="1000" step="0.1" value="${Number(config.backtestSpreadBps) || 2}"></div>`; simulationRow.parentElement?.insertBefore(executionRow, simulationRow.nextElementSibling); }
  if (simulationRow) { const policyRow = document.createElement('div'); policyRow.className = 'form-row protection-config'; policyRow.innerHTML = `<div class="field"><label for="intrabarPolicy">Si stop y take coinciden</label><select id="intrabarPolicy"><option value="conservative">Conservador · stop primero</option><option value="take-first">Take-profit primero</option></select></div><div class="field"><label>Protección</label><input value="Los gaps se ejecutan al precio disponible" disabled></div>`; simulationRow.parentElement?.insertBefore(policyRow, simulationRow.nextElementSibling); $('#intrabarPolicy').value = config.intrabarPolicy || 'conservative'; }
  const actions = $('#openData')?.parentElement;
  if (actions) { const newsRow = document.createElement('div'); newsRow.className = 'form-row news-config'; newsRow.innerHTML = `<div class="field" style="flex:1"><label for="newsFeeds">Feeds RSS HTTPS (separados por coma)</label><input id="newsFeeds" value="${esc((config.newsFeeds || []).join(', '))}" spellcheck="false"><small class="subtle">Solo fuentes HTTPS; el análisis seguirá funcionando si una fuente falla.</small></div><button class="btn" id="saveNewsFeeds">Guardar feeds</button>`; actions.parentElement?.insertBefore(newsRow, actions); $('#saveNewsFeeds').onclick = async () => { try { snapshot.settings = await window.traderAPI.saveNewsFeeds($('#newsFeeds').value); toast('Feeds de noticias guardados'); } catch (error) { toast(error.message); } }; }
  if (actions) { const restore = document.createElement('button'); restore.className = 'btn'; restore.id = 'restorePaper'; restore.textContent = 'Restaurar respaldo'; actions.appendChild(restore); restore.onclick = async () => { if (!confirm('¿Restaurar un respaldo? La cuenta actual se conservará automáticamente antes de reemplazarla.')) return; try { const restored = await window.traderAPI.restorePaperBackup(); if (restored) { snapshot.state = restored; toast('Respaldo restaurado'); navigate('dashboard'); } } catch (error) { toast(error.message); } }; }
  if (actions) { const autoRun = document.createElement('button'); autoRun.className = 'btn'; autoRun.id = 'runAutoPaper'; autoRun.textContent = 'Iniciar Auto-Paper'; actions.appendChild(autoRun); autoRun.onclick = () => openAutomationStartModal('dashboard'); }
  if (actions) { const verify = document.createElement('button'); verify.className = 'btn'; verify.id = 'verifyPaper'; verify.textContent = 'Verificar integridad'; actions.appendChild(verify); verify.onclick = async () => { try { const result = await window.traderAPI.verifyPaper(); toast(result.valid ? `Integridad correcta · ${result.ledgerEntries} asientos` : `Revisión requerida: ${result.issues.join('; ')}`); } catch (error) { toast(error.message); } }; }
  $('#saveSettings').onclick = saveSettings; $('#openData').onclick = () => window.traderAPI.openData(); $('#resetPaper').onclick = resetPaper;
}

async function saveSettings() {
  try { const model = chosenModel('#model', '#customModel'); if (!model) throw new Error('Selecciona o escribe un modelo válido.'); snapshot.settings = await window.traderAPI.saveSettings({ accountCurrency: $('#accountCurrency').value, endpoint: $('#endpoint').value, model, initialCash: $('#initialCash').value, feeRate: Number($('#feeRate').value) / 100, slippageBps: $('#slippageBps').value, backtestSpreadBps: $('#backtestSpreadBps').value, executionLatencyMs: $('#executionLatencyMs').value, limitOrderTtlMin: $('#limitOrderTtlMin').value, liquidityNotionalPerTick: $('#liquidityNotionalPerTick').value, intrabarPolicy: $('#intrabarPolicy').value, maxOrderPct: $('#maxOrderPct').value, maxDrawdownPct: $('#maxDrawdownPct').value, maxPortfolioRiskPct: $('#maxPortfolioRiskPct').value, riskPerTradePct: $('#riskPerTradePct').value, automationEnabled: $('#automationEnabled').checked, automationSymbols: $('#automationSymbols').value, automationIntervalMin: $('#automationIntervalMin').value, minConfidence: $('#minConfidence').value, llmDailyCallBudget: $('#llmDailyCallBudget').value, llmDailyBudgetUsd: $('#llmDailyBudgetUsd').value, llmInputCostPer1kUsd: $('#llmInputCostPer1kUsd').value, llmOutputCostPer1kUsd: $('#llmOutputCostPer1kUsd').value, llmFailurePauseThreshold: $('#llmFailurePauseThreshold').value }); snapshot.settings = await window.traderAPI.savePartialFill($('#partialFillPct').value); snapshot.settings = await window.traderAPI.saveRiskSettings({ maxExposurePct: $('#maxExposurePct').value, maxAssetExposurePct: $('#maxAssetExposurePct').value, maxSpreadBps: $('#maxSpreadBps').value, maxTradesPerDay: $('#maxTradesPerDay').value, maxDataAgeMs: $('#maxDataAgeMs').value }); if ($('#apiKey').value.trim()) { await window.traderAPI.saveApiKey($('#apiKey').value); snapshot.hasApiKey = true; updateKeyStatus(); } toast('Configuración guardada'); render(); }
  catch (error) { toast(error.message); }
}

async function resetPaper() {
  if (!confirm(`¿Reiniciar la simulación con ${money($('#initialCash').value)}? Se borrarán las posiciones y trades paper actuales.`)) return;
  try { snapshot.state = await window.traderAPI.resetPaper(Number($('#initialCash').value)); toast('Simulación reiniciada'); navigate('dashboard'); } catch (error) { toast(error.message); }
}

function toast(message) { const node = document.createElement('div'); node.className = 'toast'; node.textContent = message; $('#toastRoot').appendChild(node); setTimeout(() => node.remove(), 3000); }

boot().catch(error => { document.body.innerHTML = `<pre style="padding:30px;color:#ff8898">${esc(error.stack || error.message)}</pre>`; });
